CREATE TYPE "public"."origine_offre" AS ENUM('interne', 'placement');--> statement-breakpoint
CREATE TYPE "public"."statut_offre" AS ENUM('brouillon', 'publiee', 'fermee');--> statement-breakpoint
CREATE TABLE "offre" (
	"id" serial PRIMARY KEY NOT NULL,
	"slug" text NOT NULL,
	"titre" text NOT NULL,
	"categorie" text NOT NULL,
	"statut" "statut_offre" DEFAULT 'brouillon' NOT NULL,
	"origine" "origine_offre" DEFAULT 'interne' NOT NULL,
	"ligne_poste_id" integer,
	"lieu" text NOT NULL,
	"contrat" text NOT NULL,
	"secteur" text,
	"postes" integer DEFAULT 1 NOT NULL,
	"description" text NOT NULL,
	"exigences" text[] DEFAULT '{}'::text[] NOT NULL,
	"intro" text,
	"missions" text[] DEFAULT '{}'::text[] NOT NULL,
	"profil" text[] DEFAULT '{}'::text[] NOT NULL,
	"horaires" text[] DEFAULT '{}'::text[] NOT NULL,
	"salaire" jsonb,
	"accord_salaire_client" boolean DEFAULT false NOT NULL,
	"publiee_le" date,
	"valable_jusquau" date,
	"fermee_le" timestamp with time zone,
	"motif_fermeture" text,
	"ordre" integer DEFAULT 0 NOT NULL,
	"cree_par" text,
	"cree_le" timestamp with time zone DEFAULT now() NOT NULL,
	"maj_le" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "offre" ADD CONSTRAINT "offre_ligne_poste_id_ligne_poste_id_fk" FOREIGN KEY ("ligne_poste_id") REFERENCES "public"."ligne_poste"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "offre" ADD CONSTRAINT "offre_cree_par_user_id_fk" FOREIGN KEY ("cree_par") REFERENCES "public"."user"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "offre_slug_uq" ON "offre" USING btree ("slug");--> statement-breakpoint
CREATE INDEX "offre_statut_idx" ON "offre" USING btree ("statut");--> statement-breakpoint
CREATE INDEX "offre_ligne_idx" ON "offre" USING btree ("ligne_poste_id");--> statement-breakpoint
-- ADR 0013 point 6 : reprise des offres de content/jobs-data.ts (fichier retire).
INSERT INTO "offre" ("slug", "titre", "categorie", "statut", "origine", "lieu", "contrat", "secteur", "postes", "description", "exigences", "intro", "missions", "profil", "horaires", "salaire", "accord_salaire_client", "publiee_le", "valable_jusquau", "fermee_le", "ordre") VALUES
('community-manager-prospection', 'Community Manager & Chargé(e) de prospection commerciale', 'Community manager', 'publiee', 'interne', 'Douala, Cameroun', 'À préciser', NULL, 1, 'Développer la visibilité de NEXCLEAN SARL sur les réseaux sociaux et identifier de nouveaux clients via le numérique et le terrain.', ARRAY['Sérieux, honnête et véritable conscience professionnelle', 'Maîtrise de Facebook, TikTok, WhatsApp Business', 'À l''aise dans la prospection commerciale', 'Orienté(e) résultats']::text[], 'NEXCLEAN SARL, entreprise camerounaise de services aux entreprises et aux particuliers (propreté, recrutement et placement de personnel, espaces verts), recrute un(e) Community Manager & Chargé(e) de prospection commerciale pour renforcer sa présence numérique et développer son portefeuille clients à Douala. Rejoignez une entreprise ambitieuse et participez activement à son développement !', ARRAY['Assurer la veille commerciale et identifier de nouveaux clients chaque jour.', 'Prospecter sur le terrain, par téléphone, WhatsApp et les réseaux sociaux.', 'Gérer et animer les réseaux sociaux de NEXCLEAN SARL.', 'Présenter nos prestations et obtenir des rendez-vous commerciaux.', 'Transformer les prospects en clients et développer les contrats mensuels.', 'Assurer le suivi des prospects et produire un rapport hebdomadaire des résultats.', 'Collaborer avec les responsables des opérations.']::text[], ARRAY['Sérieux, honnête et doté(e) d''une véritable conscience professionnelle.', 'Orienté(e) résultats, motivé(e) par la réussite collective et la satisfaction des clients.', 'Organisé(e), autonome, ponctuel(le) et capable de travailler en équipe.', 'À l''aise dans la communication, la négociation et la prospection commerciale.', 'Maîtrisant WhatsApp Business, Facebook, TikTok et les outils numériques courants.', 'Capable de prendre des initiatives et d''atteindre des objectifs mensuels.', 'Une expérience en prospection commerciale ou en community management serait un atout.']::text[], '{}'::text[], '{"base":"40 000 FCFA/mois","bonus":"Jusqu''à 11 000 FCFA/mois selon les objectifs","target":"51 000 FCFA/mois","note":"Les objectifs et les conditions d''attribution des primes seront précisés lors de l''entretien et dans le contrat."}'::jsonb, false, NULL, NULL, NULL, 0),
('agent-caisse-akwa', 'Agent de caisse (H/F) — 2 postes', 'Agent de caisse', 'publiee', 'placement', 'Akwa, Douala (secteur bureaux de transport)', 'À préciser', 'Cave – Vente de boissons', 2, 'Accueillir les clients, encaisser les paiements, tenir la caisse avec rigueur et transparence dans une cave à Akwa.', ARRAY['Conscience professionnelle, loyauté et honnêteté', 'Bonne communication et sens du service client', 'Ponctualité, organisation, bienveillance et sourire', 'Expérience en caisse ou vente de boissons (atout)']::text[], 'NEXCLEAN SARL recrute en urgence 2 agents de caisse pour une cave située à Akwa, secteur des bureaux de transport à Douala. Vous serez en charge de l''accueil des clients et de la gestion rigoureuse de la caisse.', ARRAY['Accueillir les clients avec bienveillance, courtoisie et sourire.', 'Encaisser les paiements et rendre correctement la monnaie.', 'Enregistrer les ventes et vérifier les montants encaissés.', 'Assurer une gestion rigoureuse et transparente de la caisse.', 'Effectuer le point de caisse à chaque changement d''équipe.', 'Signaler immédiatement toute anomalie au responsable.', 'Maintenir son poste de travail propre et organisé.', 'Respecter les consignes et contribuer à la satisfaction des clients.']::text[], ARRAY['Conscience professionnelle : accomplir ses missions avec sérieux et responsabilité.', 'Loyauté et honnêteté : respecter l''entreprise, les clients et les règles de gestion de caisse.', 'Motivation : aimer son travail et avoir la volonté de bien faire.', 'Bonne communication : savoir écouter, s''exprimer clairement et travailler en équipe.', 'Bienveillance et sourire : accueillir chaque client avec respect et bonne humeur.', 'Ponctualité : respecter les horaires et les engagements professionnels.', 'Organisation : savoir gérer les priorités et tenir une caisse correctement.', 'Une expérience en caisse ou dans la vente de boissons constitue un atout.']::text[], ARRAY['Équipe de jour : 08h00 – 18h00', 'Équipe de nuit : 18h00 – 08h00', 'Rotation selon le planning établi ; horaires effectifs, pauses, rotations et jours de repos organisés conformément à la réglementation applicable.']::text[], '{"base":"50 000 FCFA/mois","fixed":true,"note":"Salaire mensuel fixe, sans condition de prime de performance."}'::jsonb, true, NULL, NULL, NULL, 1),
('community-manager', 'Community Manager (H/F)', 'Community manager', 'publiee', 'interne', 'Douala, Cameroun', 'À préciser', NULL, 1, 'Gérer et animer les réseaux sociaux de NEXCLEAN SARL (Facebook, TikTok, WhatsApp Business), créer des contenus attractifs et générer des prospects qualifiés.', ARRAY['Sérieux, honnête, motivé(e) et créatif(ve)', 'Excellente communication écrite et orale', 'Maîtrise de Facebook, TikTok, WhatsApp Business', 'Orienté(e) résultats']::text[], 'NEXCLEAN SARL renforce son équipe marketing et recrute un(e) Community Manager pour développer sa visibilité et générer de nouveaux clients grâce au numérique. Vous travaillerez sur Facebook, TikTok et WhatsApp Business pour promouvoir nos services : propreté, recrutement et placement de personnel, espaces verts.', ARRAY['Gérer et animer nos pages Facebook, TikTok et nos autres réseaux sociaux.', 'Créer des publications attractives présentant nos prestations et réalisations.', 'Assurer une veille commerciale quotidienne sur Internet.', 'Identifier des prospects à Douala, Yaoundé et Kribi.', 'Contacter les prospects par WhatsApp, téléphone et réseaux sociaux.', 'Répondre rapidement aux demandes des clients.', 'Obtenir des rendez-vous commerciaux pour l''équipe opérationnelle.', 'Suivre les prospects jusqu''à leur transformation en clients.', 'Présenter chaque semaine un rapport des actions et résultats obtenus.']::text[], ARRAY['Sérieux, honnête et doté(e) d''une véritable conscience professionnelle.', 'Motivé(e), créatif(ve) et orienté(e) résultats.', 'Loyal(e), organisé(e), autonome et ponctuel(le).', 'Doté(e) d''une excellente communication écrite et orale.', 'Bienveillant(e), respectueux(se) et capable de travailler en équipe.', 'Maîtrisant Facebook, TikTok, WhatsApp Business et les outils de création de contenu.', 'Nous privilégions les personnes qui prennent des initiatives et savent transformer leur travail en résultats concrets.']::text[], '{}'::text[], '{"base":"40 000 FCFA/mois","bonus":"Jusqu''à 11 000 FCFA/mois selon les objectifs","target":"51 000 FCFA/mois","note":"Les primes dépendront notamment des prospects qualifiés, des rendez-vous obtenus et des nouveaux clients acquis grâce aux actions numériques."}'::jsonb, false, NULL, NULL, NULL, 2),
('prospection-commerciale-terrain', 'Chargé(e) de prospection commerciale terrain (H/F)', 'Commercial', 'publiee', 'interne', 'Douala, Cameroun', 'À préciser', NULL, 1, 'Prospecter quotidiennement les entreprises, restaurants, hôtels, bureaux et commerces pour développer le portefeuille commercial de NEXCLEAN SARL.', ARRAY['Conscience professionnelle irréprochable', 'Très motivé(e) et orienté(e) objectifs', 'À l''aise dans la communication', 'Disponible pour des déplacements quotidiens']::text[], 'NEXCLEAN SARL recrute un(e) Chargé(e) de prospection commerciale terrain pour développer son portefeuille clients à Douala. Vous prospecterez quotidiennement les entreprises, restaurants, hôtels, bureaux et commerces pour présenter nos services : propreté, recrutement et placement de personnel, espaces verts.', ARRAY['Prospecter quotidiennement les entreprises, restaurants, hôtels, bureaux, commerces, résidences et autres établissements.', 'Identifier les besoins des prospects en propreté, entretien et personnel.', 'Présenter clairement les prestations et les avantages de NEXCLEAN.', 'Distribuer les supports commerciaux et recueillir les contacts professionnels.', 'Obtenir des rendez-vous pour les visites techniques et les devis.', 'Relancer régulièrement les prospects jusqu''à l''obtention d''une réponse.', 'Contribuer à la signature de nouveaux contrats mensuels.', 'Développer des partenariats commerciaux durables.', 'Renseigner le fichier de suivi commercial.', 'Présenter chaque semaine un compte rendu des visites, rendez-vous et résultats.']::text[], ARRAY['Doté(e) d''une conscience professionnelle irréprochable.', 'Sérieux(se), honnête, loyal(e) et ponctuel(le).', 'Très motivé(e) et capable de travailler avec des objectifs.', 'À l''aise dans la communication et le contact avec les clients.', 'Souriant(e), bienveillant(e), respectueux(se) et persuasif(ve).', 'Organisé(e), autonome et capable de travailler en équipe.', 'Persévérant(e) face aux refus et capable de prendre des initiatives.', 'Disponible pour effectuer des déplacements quotidiens sur le terrain.', 'Une expérience en prospection, vente ou développement commercial constitue un atout.']::text[], '{}'::text[], '{"base":"40 000 FCFA/mois","bonus":"Jusqu''à 11 000 FCFA/mois selon les objectifs","target":"51 000 FCFA/mois","note":"La prime sera liée à des objectifs commerciaux mesurables, notamment les rendez-vous qualifiés et les nouveaux contrats signés."}'::jsonb, false, NULL, NULL, NULL, 3),
('agent-nettoyage', 'Agent(e) de nettoyage', 'Agent de nettoyage', 'fermee', 'interne', 'Douala', 'À préciser', NULL, 1, 'Réaliser les prestations de nettoyage chez nos clients particuliers et professionnels.', ARRAY['Ponctualité et sérieux', 'Expérience en nettoyage appréciée', 'Disponibilité selon planning']::text[], NULL, '{}'::text[], '{}'::text[], '{}'::text[], NULL, false, NULL, NULL, now(), 4),
('chef-equipe', 'Chef(fe) d''équipe', 'Chef d''équipe', 'fermee', 'interne', 'Douala', 'À préciser', NULL, 1, 'Encadrer une équipe d''agents, organiser les interventions et contrôler la qualité.', ARRAY['Expérience en encadrement', 'Sens de l''organisation', 'Rigueur sur la qualité']::text[], NULL, '{}'::text[], '{}'::text[], '{}'::text[], NULL, false, NULL, NULL, now(), 5),
('agent-espaces-verts', 'Agent espaces verts', 'Agent espaces verts', 'fermee', 'interne', 'Douala', 'À préciser', NULL, 1, 'Tonte, débroussaillage, taille de haies et entretien des jardins de nos clients.', ARRAY['Expérience en jardinage / entretien', 'Bonne condition physique']::text[], NULL, '{}'::text[], '{}'::text[], '{}'::text[], NULL, false, NULL, NULL, now(), 6),
('commercial', 'Commercial(e)', 'Commercial', 'fermee', 'interne', 'Douala', 'À préciser', NULL, 1, 'Développer le portefeuille de clients professionnels et promouvoir les produits NEXCLEAN.', ARRAY['Aisance relationnelle', 'Expérience en prospection B2B appréciée']::text[], NULL, '{}'::text[], '{}'::text[], '{}'::text[], NULL, false, NULL, NULL, now(), 7)
